// ============================================================
// ANA-05 v4 — extrai WhatsApp + data/hora do evento do Google Agenda.
// CALIBRADO contra os 90 eventos REAIS de sac@totalquality.med.br
// (execução n8n 126929 — 20/08/2026).
//
// Correções validadas em relação ao v3:
//  1. rejeita telefone internacional (+1 ...) — caso Yuriy Oliynyk
//  2. rejeita CPF/RG/SSN/CEP mesmo SEM rótulo (4 falsos positivos
//     do v3 gravariam no lead do PACIENTE ERRADO)
//  3. a HORA vem do TÍTULO (a recepção escreve a hora real ali;
//     o bloco no calendário diverge em 69% dos casos)
//  4. nunca escreve quando o telefone é ambíguo — silêncio é seguro
// ============================================================
const DDDS = new Set([11,12,13,14,15,16,17,18,19,21,22,24,27,28,31,32,33,34,35,37,38,41,42,43,44,45,46,47,48,49,51,53,54,55,61,62,63,64,65,66,67,68,69,71,73,74,75,77,79,81,82,83,84,85,86,87,88,89,91,92,93,94,95,96,97,98,99]);

function extrairTelefone(ev) {
  const bruto = `${ev.summary || ''}\n${ev.description || ''}`;
  const limpo = bruto
    .replace(/\+(?!55)\d{1,3}[\s.\-]?[\d.\-\s]{6,15}/g, ' ')
    .replace(/\b(cpf|rg|ssn|nasc\w*|data de nasc\w*|carteirinha|matr[iI]cula|conv[eE]nio|cep)\b\s*[:\-]?\s*[\d.\-\/ ]{6,20}/gi, ' ')
    .replace(/\b\d{3}\.\d{3}\.\d{3}-?\d{2}\b/g, ' ')
    .replace(/\b\d{2}\.?\d{3}-\d{3}\b/g, ' ')
    .replace(/\b\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}\b/g, ' ');

  const cand = []; let m;
  const marcado = /(?:tel|fone|celular|cel|whats?app|whats|contato)\s*[:\-]?\s*(?:\+?55)?\s*\(?(\d{2})\)?\s*(\d{4,5})[\s.\-]?(\d{4})/gi;
  while ((m = marcado.exec(limpo)) !== null) cand.push({ p: 3, ddd: m[1], num: m[2] + m[3] });
  const paren = /\((\d{2})\)\s*(\d{4,5})[\s.\-]?(\d{4})/g;
  while ((m = paren.exec(limpo)) !== null) cand.push({ p: 2, ddd: m[1], num: m[2] + m[3] });
  const solto = /(?:\+?55)?\s*(\d{2})\s*(9\d{4}|[2-5]\d{3})[\s.\-]?(\d{4})\b/g;
  const semPont = limpo.replace(/[.\-]/g, ' ');
  while ((m = solto.exec(semPont)) !== null) cand.push({ p: 1, ddd: m[1], num: m[2] + m[3] });

  const validos = cand.filter(function (c) {
    if (!DDDS.has(parseInt(c.ddd, 10))) return false;
    if (c.num.length === 9) return /^9/.test(c.num);
    if (c.num.length === 8) return /^[2-5]/.test(c.num);
    return false;
  });
  if (!validos.length) return null;
  validos.sort(function (a, b) { return b.p - a.p; });
  return '55' + validos[0].ddd + validos[0].num;
}

function extrairHorario(ev) {
  const inicio = (ev.start && (ev.start.dateTime || ev.start.date)) || null;
  if (!inicio) return null;
  const em = inicio.match(/T(\d{2}):(\d{2})/);
  const horaBloco = em ? em[1] + ':' + em[2] : null;
  const tm = (ev.summary || '').match(/(?:^|[\s\-])(\d{1,2})\s*[hH:]\s*(\d{2})?/);
  let horaTitulo = null;
  if (tm) {
    const h = Number(tm[1]);
    if (h >= 0 && h <= 23) horaTitulo = String(h).padStart(2, '0') + ':' + (tm[2] || '00');
  }
  const hora = horaTitulo || horaBloco || '08:00';
  const hh = Number(hora.slice(0, 2));
  return {
    data: inicio.slice(0, 10),
    hora: hora,
    turno: hh < 12 ? 'manha' : (hh < 18 ? 'tarde' : 'noite'),
    fonte_hora: horaTitulo ? 'titulo' : (horaBloco ? 'bloco' : 'padrao'),
    divergencia: !!(horaTitulo && horaBloco && horaTitulo !== horaBloco)
  };
}

const out = [];
for (const item of $input.all()) {
  const ev = item.json;
  const phone = extrairTelefone(ev);
  if (!phone) continue;              // sem telefone confiavel = nao escreve (seguro)
  const h = extrairHorario(ev);
  if (!h) continue;
  out.push({ json: {
    phone: phone,
    data: h.data,
    hora: h.hora,
    turno: h.turno === 'manha' ? 'manha' : h.turno,
    cancelado: ev.status === 'cancelled',
    evento: (ev.summary || '').slice(0, 120),
    event_id: ev.id,
    fonte_hora: h.fonte_hora,
    divergencia_horario: h.divergencia
  }});
}
return out;
